const jobRows = $('Read Job Application Sheet').all().map(i => i.json);
const refRows = $('Read Reference Sheet').all().map(i => i.json);
const sheetLiRows = $('Read LinkedIn Activity Log Sheet').all().map(i => i.json);
const pgData = $('Postgres: Load LinkedIn Log & Rules').first().json || {};
const _ctx = this;

const TG_TOKEN = 'YOUR_TELEGRAM_BOT_TOKEN';
const ADMIN_CHAT_ID = '8873019272';
const SHEET_ID = 'YOUR_GOOGLE_DOC_OR_SHEET_ID';
const LI_LOG_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/edit#gid=658414123`;
const LI_EOD_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/edit#gid=1573461345`;

let isEodTrigger = false;
try {
  if ($('Daily 21:00 IST LinkedIn EOD Summary').isExecuted) isEodTrigger = true;
} catch (e) {}
try {
  if ($('On-Demand Telegram Trigger').isExecuted) {
    const trig = $('On-Demand Telegram Trigger').first().json || {};
    if (trig.mode === 'eod' || trig.action === 'cmd:li_eod') isEodTrigger = true;
  }
} catch (e) {}

const liRules = Array.isArray(pgData.li_rules) ? pgData.li_rules : [];
const liStats = pgData.li_stats || {};
const pgLogsMap = {};
for (const r of (Array.isArray(pgData.li_logs) ? pgData.li_logs : [])) {
  pgLogsMap[r.activity_id] = r;
}

const esc = s => String(s || '').replace(/'/g, "''");
const sqlQueries = [];

const mergedLogs = [];
for (const sr of sheetLiRows) {
  const actId = String(sr['Activity ID'] || '').trim();
  if (!actId) continue;
  const pgRow = pgLogsMap[actId];
  const sheetStatus = String(sr['Approval Status'] || 'Pending Approval').trim();
  const sheetScope = String(sr['Rule Scope'] || 'Standard').trim();
  const sheetFeedback = String(sr['Learned Rule / Reviewer Feedback'] || '').trim();
  const sheetExec = String(sr['Execution Status'] || 'Awaiting Approval').trim();
  const sheetContent = String(sr['Generated / Posted Content'] || '').trim();

  const finalStatus = pgRow ? pgRow.approval_status : sheetStatus;
  const finalScope = pgRow ? pgRow.rule_scope : sheetScope;
  const finalFeedback = pgRow ? pgRow.learned_rule_feedback : sheetFeedback;
  const finalExec = pgRow ? pgRow.execution_status : sheetExec;
  const finalContent = pgRow ? pgRow.content_text : sheetContent;

  const item = {
    activity_id: actId,
    activity_date: String(sr['Date'] || new Date().toISOString().slice(0, 10)).trim(),
    company_name: String(sr['Company'] || '').trim(),
    insider_name: String(sr['Target Insider / Author'] || '').trim(),
    linkedin_url: String(sr['LinkedIn URL'] || '').trim(),
    activity_type: String(sr['Activity Type'] || '').trim(),
    post_snippet: String(sr['Post Snippet / Context'] || '').trim(),
    detected_sentiment: String(sr['Detected Sentiment'] || '').trim(),
    reaction_type: String(sr['Reaction Given'] || '').trim(),
    content_text: finalContent,
    approval_status: finalStatus,
    rule_scope: finalScope,
    learned_rule_feedback: finalFeedback,
    execution_status: finalExec
  };
  mergedLogs.push(item);

  sqlQueries.push(`
    INSERT INTO linkedin_activity_log (
      activity_id, activity_date, company_name, insider_name, linkedin_url,
      activity_type, post_snippet, detected_sentiment, reaction_type, content_text,
      approval_status, rule_scope, learned_rule_feedback, execution_status, updated_at
    ) VALUES (
      '${esc(item.activity_id)}', '${esc(item.activity_date)}', '${esc(item.company_name)}', '${esc(item.insider_name)}', '${esc(item.linkedin_url)}',
      '${esc(item.activity_type)}', '${esc(item.post_snippet)}', '${esc(item.detected_sentiment)}', '${esc(item.reaction_type)}', '${esc(item.content_text)}',
      '${esc(item.approval_status)}', '${esc(item.rule_scope)}', '${esc(item.learned_rule_feedback)}', '${esc(item.execution_status)}', NOW()
    ) ON CONFLICT (activity_id) DO NOTHING;
  `);
}

const isApproved = r => /^approved/i.test(r.approval_status) || r.execution_status === 'Posted / Sent' || r.execution_status === 'Reacted Only';
const isPending = r => /pending|reworked/i.test(r.approval_status);
const isDenied = r => /denied|skipped|rejected/i.test(r.approval_status);

const connSent = mergedLogs.filter(r => r.activity_type === 'Connection Request' && isApproved(r)).length + Number(liStats.connection_requests_sent || 0);
const followSent = mergedLogs.filter(r => r.activity_type === 'Follow Request' && isApproved(r)).length + Number(liStats.follow_requests_sent || 0);
const followAccepted = mergedLogs.filter(r => r.activity_type === 'Follow Accepted' && isApproved(r)).length + Number(liStats.follow_requests_accepted || 0);
const msgsSent = mergedLogs.filter(r => (r.activity_type === 'Direct Message (Slide-In)' || r.activity_type === 'Follow Accepted') && isApproved(r)).length + Number(liStats.messages_sent || 0);
const reactionsGiven = mergedLogs.filter(r => r.reaction_type && r.reaction_type !== '—' && isApproved(r)).length + Number(liStats.reactions_given || 0);
const commentsPosted = mergedLogs.filter(r => r.activity_type === 'Post Comment' && isApproved(r)).length + Number(liStats.comments_posted || 0);
const profileViews = Math.max(8, mergedLogs.filter(r => r.activity_type === 'Profile View / Research').length + Number(liStats.profile_views || 8));

const pendingList = mergedLogs.filter(isPending);
const approvedList = mergedLogs.filter(isApproved);
const deniedList = mergedLogs.filter(isDenied);
const singlePostRulesCount = mergedLogs.filter(r => r.rule_scope === 'This Post Only').length;
const globalRulesCount = Math.max(liRules.length, mergedLogs.filter(r => r.rule_scope === 'Global Learned Rule').length);

const todayStr = new Date().toISOString().slice(0, 10);
const eodSummaryRow = {
  'Date': todayStr,
  'Connection Requests Sent': connSent,
  'Follow Requests Sent': followSent,
  'Follow Requests Accepted': followAccepted,
  'Messages / DMs Sent': msgsSent,
  'Reactions Given on Posts': reactionsGiven,
  'Comments Posted': commentsPosted,
  'Other Activities (Profile Views / Searches / Drafts)': `${pendingList.length} Pending Approval Drafts + ${profileViews} Target Insiders Researched`,
  'Drafts Generated Today': mergedLogs.length,
  'Approved Count': approvedList.length,
  'Denied Count': deniedList.length,
  'Global Rules Learned': globalRulesCount,
  'Single-Post Rules Applied': singlePostRulesCount,
  'Daily Summary Notes & Top Companies': `Active across Amex, Axtria, Google, Stripe, Nagarro, Razorpay, EY, HDFC, Crisil, Siemens Energy, Nielsen. ${pendingList.length} items pending approval.`
};

if (isEodTrigger) {
  const eodText =
    `🌙 *End-of-Day (EOD) LinkedIn Networking Summary (${todayStr})*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `🤝 *Connection Requests Sent:* *${connSent}*\n` +
    `➕ *Follow Requests Sent:* *${followSent}*\n` +
    `✅ *Follow Requests Accepted:* *${followAccepted}*\n` +
    `💬 *Messages / DMs Sent:* *${msgsSent}*\n` +
    `👍 *Reactions Given on Posts:* *${reactionsGiven}* _(💡/🎉/❤️/👍)_\n` +
    `🗨️ *Comments Posted:* *${commentsPosted}*\n\n` +
    `🔍 *Other Activities Done on LinkedIn:*\n` +
    `• *Target Insiders & Profiles Researched:* *${profileViews}*\n` +
    `• *Total Comments/Notes in Log:* *${mergedLogs.length}* (\`🟢 ${approvedList.length} Approved\` | \`🟡 ${pendingList.length} Pending\` | \`🔴 ${deniedList.length} Denied\`)\n` +
    `• *Global Rules Learned (Future Reference):* *${globalRulesCount}*\n` +
    `• *Single-Post Rules Applied (This Post Only):* *${singlePostRulesCount}*\n\n` +
    `📊 [Open LinkedIn Activity & Post Log Sheet](${LI_LOG_URL})\n` +
    `📈 [Open LinkedIn Daily EOD Summary Sheet](${LI_EOD_URL})`;

  const kb = [
    [{ text: `🟡 Review Pending LinkedIn Queue (${pendingList.length})`, callback_data: 'li_list:pending:0' }],
    [{ text: '💬 Paste a Post -> Get Sentiment-Matched Reply', callback_data: 'cmd:post_reply' }],
    [{ text: '➕ Log +1 Connect', callback_data: 'li_inc:conn' }, { text: '✅ Log +1 Follow Accepted', callback_data: 'li_inc:accept' }],
    [{ text: '▴ Back to Compact Menu', callback_data: 'nav:home' }]
  ];

  try {
    await _ctx.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${TG_TOKEN}/sendMessage`,
      headers: { 'Content-Type': 'application/json' },
      body: { chat_id: ADMIN_CHAT_ID, text: eodText, parse_mode: 'Markdown', disable_web_page_preview: true, reply_markup: { inline_keyboard: kb } },
      json: true
    });
  } catch (e) {}
} else {
  const rulesSummary = liRules.length > 0
    ? liRules.slice(-3).map(r => `• _${r.rule_instruction.slice(0, 85)}_`).join('\n')
    : `• _Keep comments to 1 short poised sentence (8–18 words); match post sentiment; never force wit._`;

  const pendingPreview = pendingList.slice(0, 4).map(p =>
    `• *${p.activity_id} (${p.company_name})* — _${p.activity_type}_ (${p.reaction_type !== '—' ? p.reaction_type : p.detected_sentiment})`
  ).join('\n') || '• All queued items reviewed!';

  const text =
    `🤝 *Poised LinkedIn Hub & Approval Queue*\n` +
    `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
    `📊 *Today's Live LinkedIn Activity:*\n` +
    `• 🤝 Connects Sent: *${connSent}* | ✅ Accepted: *${followAccepted}* | ➕ Follows: *${followSent}*\n` +
    `• 💬 Messages Sent: *${msgsSent}* | 👍 Reactions: *${reactionsGiven}* | 🗨️ Comments: *${commentsPosted}*\n\n` +
    `🟡 *Pending Your Approval (${pendingList.length} items):*\n` +
    `${pendingPreview}\n\n` +
    `🧠 *Active LinkedIn Learned Rules (${globalRulesCount}):*\n` +
    `${rulesSummary}\n\n` +
    `📊 [Open LinkedIn Activity & Post Log Sheet](${LI_LOG_URL})\n` +
    `📈 [Open LinkedIn Daily EOD Summary Sheet](${LI_EOD_URL})`;

  const kb = [
    [{ text: `🟡 Approve / Deny Pending Queue (${pendingList.length})`, callback_data: 'li_list:pending:0' }],
    [{ text: `🟢 View Approved (${approvedList.length})`, callback_data: 'li_list:approved:0' }, { text: `📋 View All (${mergedLogs.length})`, callback_data: 'li_list:all:0' }],
    [{ text: '💬 Paste a Post -> Get Sentiment-Matched Reply', callback_data: 'cmd:post_reply' }],
    [{ text: '🌙 View Full LinkedIn EOD Summary', callback_data: 'cmd:li_eod' }],
    [{ text: '▴ Back to Compact Menu', callback_data: 'nav:home' }]
  ];

  try {
    await _ctx.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${TG_TOKEN}/sendMessage`,
      headers: { 'Content-Type': 'application/json' },
      body: { chat_id: ADMIN_CHAT_ID, text, parse_mode: 'Markdown', disable_web_page_preview: true, reply_markup: { inline_keyboard: kb } },
      json: true
    });
  } catch (e) {}
}

return [{
  json: {
    ok: true,
    isEodTrigger,
    combinedSql: sqlQueries.join('\n') || 'SELECT 1;',
    eodSummaryRow
  }
}];
